// Generated by philote from page /tasks/[id]. PageBody's body is written by
// a model and pinned in philote.lock (decision-2).
/* eslint-disable @typescript-eslint/no-unused-vars -- every page gets the same imports */
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { Suspense } from "react";

import * as Icons from "lucide-react";

import { tasks } from "@/lib/api";
import { readTaskView } from "@/lib/reads";
import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";

import TaskView from "@/components/common/task-view";

export const metadata: Metadata = { title: "Task" };

export default function Page({ params }: PageProps<"/tasks/[id]">) {
    return (
        <main className="flex flex-1 flex-col">
            <PageBody
                title={"Task"}
                content={(className) => (
                    <div className={className}>
                        <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                            <Record params={params} />
                        </Suspense>
                    </div>
                )}
            />
        </main>
    );
}

// Record streams in after the page's shell, so a missing record renders
// not-found.tsx with noindex, but the response status stays 200.
async function Record({ params }: Pick<PageProps<"/tasks/[id]">, "params">) {
    await connection();
    const { id } = await params;
    const result = await tasks.get(id);
    if (!result.ok) {
        notFound();
    }
    const item = await readTaskView(result.value);
    return <TaskView {...item} />;
}

type PageBodyProps = {
    title: string;
    content: (className: string) => React.ReactNode;
};

function PageBody({ title, content }: PageBodyProps): React.ReactNode {
    return (
        <div className="mx-auto flex w-full max-w-3xl flex-col gap-4 px-4 py-6 sm:px-6 sm:py-10 lg:py-12">
            <div className="flex flex-col gap-2">
                <span className="text-xs font-medium uppercase tracking-wider text-muted-foreground">
                    {title}
                </span>
                <Separator orientation="horizontal" />
            </div>
            {content("w-full")}
        </div>
    );
}
